entries[28590] = { ["name"] = "Fläschchen des blendenden Lichts", ["text"] = "Wirken in 2.5 sek.\nReagenzien:\nTeufelslotus , Manadistel (3), Netherblüte (7), Kristallphiole\nBeruf:\nAlchemie der Scherbenwelt\nEntdeckung:\nAlchemierezepte der Scherbenwelt\n\n(2)\nBenutzen: Erhöht die Arkan-, Heilig- und Naturzaubermacht 1 Stunde lang um 16 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n26" }
entries[28591] = { ["name"] = "Fläschchen des reinen Todes", ["text"] = "Wirken in 2.5 sek.\nReagenzien:\nTeufelslotus , Manadistel (3), Alptraumranke (7), Kristallphiole\nBeruf:\nAlchemie der Scherbenwelt\nEntdeckung:\nAlchemierezepte der Scherbenwelt\n\n(2)\nBenutzen: Erhöht die Schatten-, Feuer- und Frostzaubermacht 1 Stunde lang um 16 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n26" }
