entries[30102] = { ["name"] = "Alte Bachtatze zähmen", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 20 sek.)\nBeginnt mit der Zähmung einer alten Bachtatze, damit er 15 Min. lang Euer Gefährte wird. Falls Ihr die Aufmerksamkeit des Wildtiers aus irgendeinem Grund verlieren solltet, schlägt der Vorgang der Zähmung fehl." }
