entries[30108] = { ["name"] = "Instabiles Gebrechen", ["text"] = "1 Seelensplitter 40 Meter Reichweite\nWirken in 1.5 sek.\nFügt dem Ziel im Verlauf von 8 Sek. (72.5% der Zaubermacht) Schattenschaden zu. Ziele können mit bis zu 5 Stapeln von 'Instabiles Gebrechen' gleichzeitig belegt werden.\n\nIhr fügt Zielen, die von Euch mit 'Instabiles Gebrechen' belegt wurden, 10% mehr Schaden zu.\n\nBeim Bannen fügt der Effekt dem Bannenden [(18.125% der Zaubermacht) * 400 / 100] Schaden zu und bringt ihn für 4 Sek. zum Schweigen." }
entries[30109] = { ["name"] = "Schleimexplosion", ["text"] = "Sofort\nFügt Gegnern in der Nähe 103 Naturschaden zu und verringert ihre Bewegungsgeschwindigkeit 5 Sek. lang um 50%." }
entries[30110] = { ["name"] = "Mutierte Sporen", ["text"] = "Sofort\nFügt nahen feindlichen Zielen alle 3 Sek. 100 Naturschaden zu." }
entries[30111] = { ["name"] = "Mutierte Sporen", ["text"] = "Sofort\nVerursacht alle 3 Sek. bei nahen Einheiten 100 Naturschaden." }
entries[30112] = { ["name"] = "Rasender Sturzflug", ["text"] = "8 - 25 Meter Reichweite\nSofort\nStuns an enemy, rendering it unable to move or attack for 2 Sek..\nCharges to an enemy.\nInflicts Physical damage to an enemy." }
entries[30113] = { ["name"] = "Eitriger Biss", ["text"] = "Nahkampfreichweite\nSofort\nErhöht den durch gegnerische Treffer erlittenen Schaden 30 Sek. lang um 10%." }
entries[30115] = { ["name"] = "Opferung", ["text"] = "50 Meter Reichweite\nWirken in 1 sek.\nOpfert das Ziel den Alten Göttern, betäubt es und entzieht ihm 30 Sek. lang alle 1 Sek. 10 Gesundheit." }
entries[30120] = { ["name"] = "Dämonenketten beschwören", ["text"] = "30 Meter Reichweite\nSofort\nBeschwört Dämonenketten, um das Opferungsritual aufrechtzuerhalten." }
entries[30121] = { ["name"] = "Kräftiges Heulen", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind normalen Schaden plus 0 zu und stößt ihn zurück." }
entries[30122] = { ["name"] = "Seuchenwolke", ["text"] = "100 Meter Reichweite\nKanalisiert\nVerursacht bei feindlichen Zielen innerhalb von 21 Metern 39 Naturschaden." }
entries[30127] = { ["name"] = "Sengende Schlacke", ["text"] = "Unbegrenzte Reichweite\nSofort\n1458 Feuerschaden im Verlauf von 18 Sek." }
entries[30128] = { ["name"] = "Rauchende Explosion", ["text"] = "80 Meter Reichweite\nWirken in 1 sek.\nFügt dem Ziel 1606 körperlichen Schaden zu und zusätzlich regelmäßigen Feuerschaden." }
entries[30129] = { ["name"] = "Verbrannte Erde", ["text"] = "Unbegrenzte Reichweite\nWirken in 1 sek.\nVersengt den Boden, setzt ihn in Flammen und fügt in dem in Brand gesetzten Gebiet 30 Sek. lang 11150 Schaden zu." }
