entries[30131] = { ["name"] = "Spalten", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nFügt einem Feind und seinem nächsten Verbündeten Waffenschaden plus 119 zu, wirkt auf bis zu 2 Ziele." }
entries[30138] = { ["name"] = "Schattenschock", ["text"] = "Sofort\nPeitscht sofort in der Nähe befindliche Feinde mit dunkler Magie und verursacht 13 Schattenschaden." }
