entries[30146] = { ["name"] = "Teufelswache beschwören", ["text"] = "1 Seelensplitter\nWirken in 6 sek.\nBeschwört eine Teufelswache, die unter Eurem Befehl steht und Euch als mächtiger Nahkämpfer dient." }
entries[30151] = { ["name"] = "Verfolgung", ["text"] = "20 Energie 6 - 25 Meter Reichweite\nSofort 15 sek. Abklingzeit\nDie Teufelswache stürmt auf einen Gegner zu, was [0.1326 * (Zaubermacht * 0.5) * 1 * (1 + Vielseitigkeit)] körperlichen Schaden verursacht und ihre Bewegungsgeschwindigkeit 8 Sek. lang um 30% erhöht.\n\nAutomatisches Wirken:\nWird immer eingesetzt, wenn die Teufelswache weiter als 8 Meter vom Ziel entfernt ist.\n\n(Mit Rechtsklick umschalten)" }
entries[30152] = { ["name"] = "Ash'ana", ["text"] = "Sofort\nMit Rechtsklick Euer Tigerbaby beschwören oder wieder freigeben." }
entries[30153] = { ["name"] = "Verfolgung", ["text"] = "Unbegrenzte Reichweite\nSofort\nStürmt auf einen Gegner zu, verursacht (13.26% der Angriffskraft)% Waffenschaden und erhöht die Bewegungsgeschwindigkeit der Teufelswache 8 Sek. lang um 30%.\n\nAutomatisches Wirken:\nWird immer eingesetzt, wenn die Teufelswache weiter als 8 Meter vom Ziel entfernt ist.\n\n(Mit Rechtsklick umschalten)" }
entries[30155] = { ["name"] = "Heilung", ["text"] = "215 Mana 40 Meter Reichweite\nWirken in 3 sek.\nRuft heilige Magie an, um einen Verbündeten zu heilen." }
