entries[30174] = { ["name"] = "Reitschildkröte", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine Reitschildkröte und gibt sie wieder frei. Sie mag langsam sein, aber wenigstens braucht Ihr nicht laufen!\n\"Mit Ruhe und Gelassenheit kommt man vielleicht nicht als Erster durchs Ziel, doch kommt man wenigstens an... irgendwann.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
